feed:
Jekyll


{{ site.time | date_to_xmlschema }}
{{ page.url | absolute_url }}
{{ site.title | smartify | xml_escape }}{% if include.category %} - {{ include.category | capitalize }}{% endif %}
{% if site.description %}
{{ site.description | xml_escape }}
{% endif %}

{%- if include.category -%}
  {%- assign feed_posts = site.categories[include.category] -%}
{%- else -%}
  {%- assign feed_posts = site.posts -%}
{%- endif -%}
{%- assign post_limit = site.feed.posts_limit | default: 200 -%}

{% for post in feed_posts limit: post_limit %}

  {{ post.title | smartify | strip_html | normalize_whitespace | xml_escape }}

  {{ post.date | date_to_xmlschema }}
  {{ post.last_modified_at | default: post.date | date_to_xmlschema }}
  {{ post.id | absolute_url }}

    {%- capture clean_content -%}
      {%- assign parts = post.content | split: '' -%}
      {%- for part in parts -%}
        {%- if part contains '' -%}
          {{ part | split: '' | last }}
        {%- else -%}
          {{ part }}
        {%- endif -%}
      {%- endfor -%}
    {%- endcapture -%}
    {{ clean_content | strip | xml_escape }}

  {% if post.author %}

    {{ post.author | xml_escape }}

  {% endif %}
  {% if post.excerpt %}
  {{ post.excerpt | strip_html | normalize_whitespace | xml_escape }}
  {% endif %}

{% endfor %}
